head.script:
// 테스트 설명, 유효성 값 설정
//  분리 초점 : groupbyZone=true 이면 adaptive 속성에 의한 적응형 레이아웃 모드가 비활성화 됨
//  (adaptive='crosstab' + 브라우저 너비 <= adaptiveThreshold 이면 w2grid_adaptive_crosstab 클래스가 적용되나,
//   groupbyZone=true 이면 적용되지 않음)
scwin.tData = {
    "description" : "[gridView > P > groupbyZone]<br/>GridView 컴포넌트의 상단에 GroupBy Zone 을 표시할지 설정합니다.",
    "validation" : [
        "groupbyZone=true 이면 adaptive 속성에 의한 적응형 레이아웃 모드가 비활성화 됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    con_groupbyZone.setValue("2");   // 기본 true
    scwin.comp_init();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : adaptive='crosstab' + adaptiveThreshold='2000' 고정, groupbyZone 은 con 선택값
//  - 브라우저 너비 <= 2000 이면 adaptive 조건 충족 → groupbyZone=false 면 적응형(w2grid_adaptive_crosstab) 적용
//  - groupbyZone=true 이면 적응형 비활성화(클래스 미적용)
scwin.comp_init = async function () {
    if (typeof dlt_bind !== 'undefined') { $p.data.remove("dlt_bind"); }
    if (typeof target1 !== 'undefined') { target1.remove(); }

    let vGroupbyZone = con_groupbyZone.getText();
    let properties = { adaptive: "crosstab", adaptiveThreshold: "2000" };
    if (vGroupbyZone === 'true') { properties.groupbyZone = true; }
    else if (vGroupbyZone === 'false') { properties.groupbyZone = false; }

    $c.gcm.createLabel('label="[전제] adaptive=crosstab, adaptiveThreshold=2000 고정 (브라우저 너비 2000 이하면 적응형 조건 충족)\n[현재] groupbyZone=' + (vGroupbyZone === '' ? '(미설정)' : vGroupbyZone) + '\n[확인] [adaptive 상태 확인] 클릭 → groupbyZone=true 이면 적응형(w2grid_adaptive_crosstab) 미적용, false/미설정이면 적용됨"', '', 'label1');

    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    await scwin.createGridView(properties);
}



scwin.fillData = function () {
    let rows = [
        { col1: "서울", col2: "강남", col3: "A", col4: "100" },
        { col1: "서울", col2: "송파", col3: "B", col4: "200" },
        { col1: "부산", col2: "해운대", col3: "C", col4: "300" },
        { col1: "부산", col2: "수영", col3: "D", col4: "400" },
        { col1: "대구", col2: "수성", col3: "E", col4: "500" },
        { col1: "대구", col2: "달서", col3: "F", col4: "600" }
    ];
    dlt_bind.setJSON(rows, false);
}



scwin.createGridView = async function (properties) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let cList = $c.gcm.createCList(properties);

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' id="" dataList="data:dlt_bind" style="width:560px;height:300px;">';
    s += '<w2:caption style="" id="caption1" value="groupbyZone + adaptive 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="140" style="" inputType="text" id="column1" value="지역"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="column2" value="상세"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="column3" value="구분"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="column4" value="값"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="140" style="" inputType="text" id="col1"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="col2"></w2:column>';
    s += '<w2:column width="140" style="" inputType="text" id="col3"></w2:column>';
    s += '<w2:column width="*" style="" inputType="text" id="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// adaptive 상태 확인 : 적응형 활성 클래스(w2grid_adaptive_crosstab) 적용 여부 실측
//  - groupbyZone=true : 적응형 조건을 충족해도 비활성(클래스 미적용)
//  - groupbyZone=false/미설정 : 조건 충족 시 활성(클래스 적용)
scwin.btn_checkAdaptive_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let hasAdaptive = target1.hasClass ? target1.hasClass("w2grid_adaptive_crosstab") : false;

    bottom.setReturnValue("[전제] adaptive=" + target1.options.adaptive
        + " / adaptiveThreshold=" + target1.options.adaptiveThreshold
        + " / groupbyZone=" + target1.options.groupbyZone);
    bottom.setReturnValue("[브라우저 너비] " + window.innerWidth + " (threshold 이하이면 적응형 조건 충족)");
    bottom.setReturnValue("[적응형(w2grid_adaptive_crosstab) 적용] " + (hasAdaptive ? "활성" : "비활성")
        + " -> groupbyZone=true 이면 비활성이 기대값");
}
